package com.digitalbase.ticketing.model;import com.digitalbase.ticketing.enums.ActivityType;import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;import lombok.*;import org.hibernate.annotations.CreationTimestamp;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.math.BigDecimal;import java.time.Instant;@Entity@Table(name = "ticket_activities")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builderpublic class TicketActivity {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "ticket_id", nullable = false)    @JsonIgnore    private Ticket ticket;    @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "user_id", nullable = false)    private User user;    @Enumerated(EnumType.STRING)    @Column(name = "activity_type", nullable = false)    private ActivityType activityType;    @Lob    @JdbcTypeCode(SqlTypes.LONGVARCHAR)    private String message;    @Column(name = "time_deducted", precision = 5, scale = 2)    private BigDecimal timeDeducted = BigDecimal.ZERO;    @CreationTimestamp    @Column(name = "created_at", updatable = false)    private Instant createdAt;}